{% for e in group.entries %}
  {% set ttarget = e.urls.project or e.urls.paper or "" %}
  <article class="entry{% if e.preview %} has-img{% endif %}" data-key="{{ e.key }}">
    {% if e.preview %}
    <a class="thumb" {% if ttarget %}href="{{ ttarget }}" target="_blank" rel="noopener"{% endif %}>
      <img src="{{ e.preview }}" alt="" width="120" height="160" loading="lazy">
    </a>
    {% endif %}
    <div class="entry-body">
      <div class="title">{{ e.title }}{% if e.note %}<span class="note-star">{{ e.note }}</span>{% endif %}</div>
      <div class="authors">{% for a in e.authors %}{% if not loop.first %}, {% endif %}{% if a.me %}<em>{{ a.name }}</em>{% else %}{{ a.name }}{% endif %}{% endfor %}</div>
      <div class="meta">{{ e.venue }}{% if not e.venue_has_year %}, {{ e.year }}{% endif %}{% if e.month %}, {{ e.month }}{% endif %}</div>
      {% set links = [] %}
      {% if e.urls.paper %}{% set _ = links.append(("Paper", e.urls.paper)) %}{% endif %}
      {% if e.urls.project %}{% set _ = links.append(("Project", e.urls.project)) %}{% endif %}
      {% if e.urls.code %}{% set _ = links.append(("Code", e.urls.code)) %}{% endif %}
      {% if e.urls.video %}{% set _ = links.append(("Video", e.urls.video)) %}{% endif %}
      {% if e.urls.slides %}{% set _ = links.append(("Slides", e.urls.slides)) %}{% endif %}
      {% if e.urls.supplement %}{% set _ = links.append(("Supplement", e.urls.supplement)) %}{% endif %}
      {% if e.doi and not e.urls.paper %}{% set _ = links.append(("DOI", e.doi)) %}{% endif %}
      {% if links %}
      <div class="badges">
        {% for label, href in links %}
        <a class="badge" href="{{ href }}" target="_blank" rel="noopener">
          <svg class="i" viewBox="0 0 24 24"><path d="M7 17 17 7M9 7h8v8"/></svg>{{ label }}
        </a>
        {% endfor %}
      </div>
      {% endif %}
    </div>
  </article>
{% endfor %}

