    function: "() => {\n      const clean = s => (s||'').replace(/\\s+/g,' ').trim();\n      const h1 = document.querySelector('h3');\n      const title = h1 ? clean(h1.textContent) : (document.title||'');\n      // authors line\n      const authEls = Array.from(document.querySelectorAll('.gs_gray, .gsc_ah, span[itemprop=\"author\"]'));\n      let authors = '';\n      const m = document.querySelector('[itemprop=\"author\"], .gsc_ah');\n      if(m){ authors = clean(m.textContent); }\n      // all links on the page that look paper/project/code\n      const links = Array.from(document.querySelectorAll('a'))\n        .map(a=>({t:clean(a.textContent), h:a.href}))\n        .filter(x=>x.h && /arxiv\\.org|doi\\.org|github\\.com|scholar\\.google|huggingface|project|\\.cc\\b|research\\.|\\bdomain/i.test(x.h) && !/scholar\\.google\\.com\\/(citations|scholar\\?)/.test(x.h));\n      // dedupe\n      const seen=new Set(); const outL=[];\n      for(const L of links){ const k=L.h; if(!seen.has(k)){seen.add(k); outL.push(L);} }\n      return {title, authors, links: outL.slice(0,14), bodyText: clean(document.body.innerText).slice(0, 1200)};\n    }"
